'use strict';

const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const { createHash } = require('node:crypto');
const { spawn } = require('node:child_process');

// Earth and cloud textures from the Three.js r167 examples, converted to compact JPEGs.
const graphicsAssets = {
    earth: Buffer.from('', 'base64'),
    clouds: Buffer.from('', 'base64'),
};

const baselineHash = 'c749c90bbc6de485b4d2a4b823d84e7faccae8aceb2ef2691908cdb4d2295f31';

function applyTier4Preview({ THREE, scene, earthStatus, textTexture }) {
    const atrium = scene.getObjectByName('TF_REFERENCE_ATRIUM_V2');
    const ceiling = scene.children.find((object) =>
        object.isMesh && object.position.y === 11.4 &&
        object.geometry.parameters?.width === 42 &&
        object.geometry.parameters?.depth === 32);
    const tiles = atrium?.children.filter((object) =>
        object.isMesh && object.position.y === 0.015 &&
        object.geometry.parameters?.width === 2.47 &&
        object.geometry.parameters?.depth === 2.47);

    if (!ceiling || !tiles?.length || !earthStatus?.isMesh) {
        console.warn('Tier 4 preview skipped: expected atrium surfaces were not found.');
        return;
    }

    const tileFinish = tiles[0].material.clone();
    tileFinish.color.set('#707b85');
    tileFinish.roughness = 0.76;
    tileFinish.metalness = 0.04;
    for (const tile of tiles) {
        tile.material = tileFinish;
        tile.scale.x *= 2.49 / 2.47;
        tile.scale.z *= 2.49 / 2.47;
    }

    const ceilingFinish = ceiling.material.clone();
    ceilingFinish.map = null;
    ceilingFinish.color.set('#24323e');
    ceilingFinish.roughness = 0.9;
    ceilingFinish.metalness = 0.03;
    ceiling.material = ceilingFinish;

    // Local fill lights with limited reach. Existing shadows and exposure stay in control.
    const lighting = new THREE.Group();
    lighting.name = 'TF_TIER4_PREVIEW_LIGHTING';
    const warm = new THREE.PointLight(0xffd0a0, 29, 8, 2);
    const cool = new THREE.PointLight(0x8dcfff, 32, 8, 2);
    warm.position.set(-11, 4.1, -5.5);
    cool.position.set(11, 4.1, -5.5);
    lighting.add(warm, cool);
    scene.add(lighting);

    // Move the Earth caption below the globe, clear of the development-room entrance.
    const caption = earthStatus.material.clone();
    caption.map = textTexture('EARTH', 'VISUAL PROTOTYPE');
    caption.map.colorSpace = THREE.SRGBColorSpace;
    earthStatus.material = caption;
    earthStatus.position.set(0, 1.78, -1.9);
    earthStatus.scale.set(0.7, 0.74, 1);

    const studio = new THREE.Group();
    studio.name = 'TF_TIER4_STUDIO_ARCHITECTURE';
    const finishes = {
        graphite: new THREE.MeshStandardMaterial({ color: 0x222c33, roughness: 0.84 }),
        felt: new THREE.MeshStandardMaterial({ color: 0x111a21, roughness: 0.99 }),
        steel: new THREE.MeshStandardMaterial({ color: 0x617482, roughness: 0.4, metalness: 0.55 }),
        oak: new THREE.MeshStandardMaterial({ color: 0x73523b, roughness: 0.63 }),
        diffuser: new THREE.MeshStandardMaterial({
            color: 0xffdeb5, emissive: 0xffc78d, emissiveIntensity: 0.72, roughness: 0.6
        }),
        guide: new THREE.MeshStandardMaterial({
            color: 0x407583, emissive: 0x318594, emissiveIntensity: 0.78, roughness: 0.62
        })
    };
    const parts = Object.fromEntries(Object.keys(finishes).map((key) => [key, []]));
    const add = (finish, width, height, depth, x, y, z) =>
        parts[finish].push([width, height, depth, x, y, z]);

    // Acoustic rafts flank the projector's open center lane.
    for (const x of [-10.6, 10.6]) {
        for (const z of [-8.1, 0, 8.1]) {
            add('graphite', 11.8, 0.36, 6.1, x, 10.15, z);
            add('felt', 11.44, 0.045, 5.72, x, 9.95, z);
            for (const offset of [-4.8, -2.4, 0, 2.4, 4.8]) {
                add('oak', 0.12, 0.12, 5.5, x + offset, 9.86, z);
            }
            for (const edge of [-1, 1]) {
                add('diffuser', 10.8, 0.032, 0.15, x, 9.865, z + edge * 2.77);
            }
        }
    }

    // Keep the side-wall projection areas clear by restricting panels to the corners.
    for (const side of [-1, 1]) {
        for (const z of [-12, 12]) {
            add('graphite', 0.10, 5.4, 3.2, side * 20.51, 4.85, z);
            for (let slat = -5; slat <= 5; slat++) {
                add('oak', 0.10, 5.16, 0.12, side * 20.40, 4.85, z + slat * 0.24);
            }
            add('diffuser', 0.045, 0.11, 2.8, side * 20.31, 7.46, z);
        }
    }

    // Detail the six existing consoles in place, retaining their interaction targets.
    const desktopShape = new THREE.Shape();
    desktopShape.moveTo(-2.12, -0.81);
    desktopShape.lineTo(2.12, -0.81);
    desktopShape.lineTo(2.12, 0.81);
    desktopShape.lineTo(-2.12, 0.81);
    desktopShape.closePath();
    const desktopGeometry = new THREE.ExtrudeGeometry(desktopShape, {
        depth: 0.028, bevelThickness: 0.017, bevelSize: 0.026, bevelSegments: 2, steps: 1
    });
    desktopGeometry.rotateX(-Math.PI / 2);
    for (const [x, z] of [[0, -9], [-12, -7], [12, -7], [-13, 7], [13, 7], [0, 10]]) {
        const desktopMesh = new THREE.Mesh(desktopGeometry, finishes.oak);
        desktopMesh.position.set(x, 1.34, z);
        desktopMesh.raycast = () => {};
        studio.add(desktopMesh);
        add('felt', 2.94, 0.017, 0.65, x, 1.385, z + 0.29);
        add('steel', 1.18, 0.036, 0.30, x, 1.41, z + 0.37);
        for (const row of [-1, 0, 1]) {
            for (let key = -6; key <= 6; key++) {
                add('graphite', 0.071, 0.013, 0.061, x + key * 0.081, 1.433, z + 0.37 + row * 0.077);
            }
        }
        add('steel', 0.25, 0.49, 0.13, x, 1.68, z - 0.57);
        add('guide', 2.28, 0.025, 0.016, x, 1.79, z - 0.42);
    }

    // Flush markers anchor the exhibit without adding a platform in the walking path.
    for (const x of [-2.15, 2.15]) add('guide', 0.055, 0.012, 3.5, x, 0.033, -2);
    for (const z of [-3.75, -0.25]) add('steel', 4.35, 0.012, 0.055, 0, 0.033, z);

    const unit = new THREE.BoxGeometry(1, 1, 1);
    const transform = new THREE.Object3D();
    for (const [finish, components] of Object.entries(parts)) {
        const batch = new THREE.InstancedMesh(unit, finishes[finish], components.length);
        batch.name = finish;
        components.forEach(([width, height, depth, x, y, z], index) => {
            transform.scale.set(width, height, depth);
            transform.position.set(x, y, z);
            transform.updateMatrix();
            batch.setMatrixAt(index, transform.matrix);
        });
        batch.instanceMatrix.needsUpdate = true;
        studio.add(batch);
    }
    scene.add(studio);
    return studio;
}

function applyIntegratedGraphics({ THREE, scene, renderer, sphere, earthStatus, studio }) {
    function materialMaps(kind) {
        const size = 128;
        const heights = new Float32Array(size * size);
        const base = new Uint8Array(size * size * 4);
        const normal = new Uint8Array(base.length);
        const roughness = new Uint8Array(base.length);
        const swatches = { stone: [128, 137, 143], fabric: [44, 54, 61], metal: [146, 156, 163] };
        const color = swatches[kind];
        let seed = 18203;
        for (let y = 0; y < size; y++) {
            for (let x = 0; x < size; x++) {
                seed = (Math.imul(1664525, seed) + 1013904223) >>> 0;
                const noise = seed / 4294967296 - 0.5;
                const grain = kind === 'fabric'
                    ? 0.32 * Math.sin(x * Math.PI / 2) * Math.sin(y * Math.PI / 2)
                    : kind === 'metal' ? 0.25 * Math.sin(y * Math.PI / 2)
                        : 0.21 * Math.sin((x + y) * Math.PI / 32);
                heights[y * size + x] = grain + noise * 0.22;
            }
        }
        const at = (x, y) => heights[((y + size) % size) * size + (x + size) % size];
        for (let y = 0; y < size; y++) {
            for (let x = 0; x < size; x++) {
                const i = (y * size + x) * 4;
                const h = at(x, y);
                for (let c = 0; c < 3; c++) base[i + c] = color[c] + h * 34;
                const nx = (at(x - 1, y) - at(x + 1, y)) * 0.32;
                const ny = (at(x, y - 1) - at(x, y + 1)) * 0.32;
                const length = Math.hypot(nx, ny, 1);
                normal.set([128 + 127 * nx / length, 128 + 127 * ny / length, 128 + 127 / length, 255], i);
                const rough = Math.round((({ stone: 0.73, fabric: 0.93, metal: 0.35 })[kind] + h * 0.12) * 255);
                roughness.set([rough, rough, rough, 255], i);
                base[i + 3] = 255;
            }
        }
        function texture(data, colorSpace) {
            const map = new THREE.DataTexture(data, size, size);
            map.colorSpace = colorSpace;
            map.wrapS = map.wrapT = THREE.RepeatWrapping;
            map.magFilter = THREE.LinearFilter;
            map.minFilter = THREE.LinearMipmapLinearFilter;
            map.generateMipmaps = true;
            map.repeat.set(2, 2);
            map.needsUpdate = true;
            return map;
        }
        return {
            map: texture(base, THREE.SRGBColorSpace),
            normalMap: texture(normal, THREE.NoColorSpace),
            roughnessMap: texture(roughness, THREE.NoColorSpace)
        };
    }

    const atrium = scene.getObjectByName('TF_REFERENCE_ATRIUM_V2');
    const tile = atrium.children.find(object => object.geometry?.parameters?.width === 2.47);
    const finishes = [
        [tile.material, 'stone', 0.04],
        [studio.getObjectByName('felt').material, 'fabric', 0],
        [studio.getObjectByName('steel').material, 'metal', 0.85]
    ];
    for (const [material, kind, metalness] of finishes) {
        Object.assign(material, materialMaps(kind), { roughness: 1, metalness });
        material.color.set(0xffffff);
        material.needsUpdate = true;
    }

    const reflectionStage = new THREE.Scene();
    reflectionStage.background = new THREE.Color(0x657385);
    const panel = new THREE.PlaneGeometry(4, 2);
    const panels = [
        [new THREE.Color(0xffdfba).multiplyScalar(2.5), 0, 4, -3],
        [new THREE.Color(0x8bd2ff).multiplyScalar(1.7), -4, 1, 2]
    ];
    for (const [color, x, y, z] of panels) {
        const mesh = new THREE.Mesh(panel, new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide }));
        mesh.position.set(x, y, z);
        mesh.lookAt(0, 0, 0);
        reflectionStage.add(mesh);
    }
    const pmrem = new THREE.PMREMGenerator(renderer);
    try {
        const reflections = pmrem.fromScene(reflectionStage, 0.12);
        for (const [material] of finishes) {
            material.envMap = reflections.texture;
            material.envMapIntensity = 0.48;
            material.needsUpdate = true;
        }
    } catch (error) {
        console.warn('Graphics reflections unavailable. Using the room lights.', error);
    } finally {
        pmrem.dispose();
        panel.dispose();
        reflectionStage.children.forEach(mesh => mesh.material.dispose());
    }

    // Use a static contact gradient with no additional shadow-map pass.
    const size = 64;
    const pixels = new Uint8Array(size * size * 4);
    for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) {
        const radius = Math.hypot((x + 0.5) / 32 - 1, (y + 0.5) / 32 - 1);
        pixels[(y * size + x) * 4 + 3] = 155 * Math.max(0, 1 - radius) ** 2;
    }
    const contactMap = new THREE.DataTexture(pixels, size, size);
    contactMap.magFilter = contactMap.minFilter = THREE.LinearFilter;
    contactMap.needsUpdate = true;
    const shadowMaterial = new THREE.MeshBasicMaterial({
        map: contactMap, transparent: true, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -1
    });
    const shadowGeometry = new THREE.PlaneGeometry(5.6, 2.9);
    for (const [x, z] of [[0, -9], [-12, -7], [12, -7], [-13, 7], [13, 7], [0, 10]]) {
        const shadow = new THREE.Mesh(shadowGeometry, shadowMaterial);
        shadow.rotation.x = -Math.PI / 2;
        shadow.position.set(x, 0.028, z);
        shadow.raycast = () => {};
        studio.add(shadow);
    }

    // Keep the original sign mesh, depth behavior, and raycast targets.
    scene.traverse(object => {
        const material = object.material;
        const image = material?.map?.image;
        if (object.geometry?.type !== 'PlaneGeometry' || !material?.isMeshBasicMaterial ||
            material.side !== THREE.DoubleSide || image?.width !== 900 || image?.height !== 220) return;
        material.onBeforeCompile = shader => {
            const signMap = THREE.ShaderChunk.map_fragment.replaceAll('vMapUv', 'tfSignUv');
            shader.fragmentShader = shader.fragmentShader.replace('#include <map_fragment>',
                'vec2 tfSignUv = gl_FrontFacing ? vMapUv : vec2(1.0 - vMapUv.x, vMapUv.y);\n' + signMap);
        };
        material.customProgramCacheKey = () => 'towerflow-sign-facing-v1';
        material.needsUpdate = true;
    });

    const loader = new THREE.TextureLoader();
    loader.load('/graphics/earth.jpg', texture => {
        texture.colorSpace = THREE.SRGBColorSpace;
        const surface = sphere.material.clone();
        surface.map = texture;
        surface.roughness = 0.83;
        surface.emissive.set(0x061224);
        surface.emissiveIntensity = 0.23;
        surface.needsUpdate = true;
        sphere.material = surface;
        earthStatus.userData.tfEarthSurface = 'reference texture';
    }, undefined, () => console.warn('Earth surface unavailable. Using the original globe.'));
    loader.load('/graphics/clouds.jpg', texture => {
        const clouds = new THREE.Mesh(sphere.geometry, new THREE.MeshBasicMaterial({
            color: 0xe6f2ff, alphaMap: texture, transparent: true, opacity: 0.47, depthWrite: false
        }));
        clouds.scale.setScalar(1.012);
        clouds.raycast = () => {};
        clouds.onBeforeRender = () => { clouds.rotation.y = performance.now() * 0.000008; };
        sphere.add(clouds);
    }, undefined, () => console.warn('Earth cloud texture unavailable.'));
    const atmosphere = new THREE.Mesh(sphere.geometry, new THREE.ShaderMaterial({
        transparent: true,
        depthWrite: false,
        side: THREE.FrontSide,
        blending: THREE.AdditiveBlending,
        vertexShader: `
            varying vec3 tfNormal;
            varying vec3 tfView;
            void main() {
                vec4 p = modelViewMatrix * vec4(position, 1.0);
                tfNormal = normalize(normalMatrix * normal);
                tfView = -p.xyz;
                gl_Position = projectionMatrix * p;
            }`,
        fragmentShader: `
            varying vec3 tfNormal;
            varying vec3 tfView;
            void main() {
                float edge = pow(1.0 - max(dot(normalize(tfNormal), normalize(tfView)), 0.0), 4.0);
                gl_FragColor = vec4(0.15, 0.48, 1.0, edge * 0.42);
                #include <colorspace_fragment>
            }`
    }));
    atmosphere.scale.setScalar(1.027);
    atmosphere.raycast = () => {};
    sphere.add(atmosphere);
}

function applyReferenceLook({ THREE, scene, stations }) {
    const stationLabels = {
        ide: 'Code Nexus', ai: 'AI Studio', work: 'Tactical Board',
        team: 'Team Portal', music: 'Sound Garden', links: 'Link Hub'
    };
    const layout = stations.filter(station => Object.hasOwn(stationLabels, station.id))
        .filter((station, index, list) => list.findIndex(item => item.id === station.id) === index);
    const atrium = scene.getObjectByName('TF_REFERENCE_ATRIUM_V2');
    const tiles = atrium?.children.filter(mesh =>
        mesh.position.y === 0.015 && mesh.geometry?.parameters?.width === 2.47);
    const walls = scene.children.filter(mesh => {
        const size = mesh.geometry?.parameters;
        return mesh.isMesh && Math.abs(mesh.position.x) <= 21 &&
            mesh.position.y === 5.5 && size?.height === 11 &&
            ((size.width === 42 && size.depth === 0.6) || (size.width === 0.6 && size.depth === 32));
    });
    if (walls.length !== 4) {
        throw Error('Reference look could not identify the original surfaces.');
    }
    const room = new THREE.Group();
    room.name = 'TF_REFERENCE_INTERIOR';
    let randomState = 78123;
    const random = () => {
        randomState = (Math.imul(1664525, randomState) + 1013904223) >>> 0;
        return randomState / 4294967296;
    };

    function canvasTexture(width, height, draw) {
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const context = canvas.getContext('2d');
        if (!context) throw Error('Canvas textures are unavailable.');
        draw(context, width, height);
        const texture = new THREE.CanvasTexture(canvas);
        texture.colorSpace = THREE.SRGBColorSpace;
        texture.anisotropy = 4;
        return texture;
    }

    // Flowing resin with luminous branching pigment and sparse copper flecks.
    const resin = canvasTexture(1024, 768, (ctx, width, height) => {
        ctx.fillStyle = '#060b1b';
        ctx.fillRect(0, 0, width, height);
        const channels = [0.04, 0.21, 0.38, 0.58, 0.77, 0.95];
        const offsets = channels.map(() => random() * 6.28);
        const curve = (y, channel) => channels[channel] * width +
            Math.sin(y / 115 + offsets[channel]) * 88 + Math.cos(y / 58 + channel) * 24;
        for (let channel = 0; channel < channels.length; channel++) {
            for (const [lineWidth, color] of [[75, '#0b193c'], [44, '#12275e'], [21, '#193b96'],
                [9, channel % 2 ? '#9452f0' : '#237de8'], [3.5, channel % 2 ? '#e9aafa' : '#8be8ff']]) {
                ctx.beginPath();
                for (let y = 0; y <= height; y += 4) {
                    const x = curve(y, channel);
                    if (y === 0) ctx.moveTo(x, y);
                    else ctx.lineTo(x, y);
                }
                ctx.lineWidth = lineWidth;
                ctx.strokeStyle = color;
                ctx.stroke();
            }
        }
        for (let i = 0; i < 3200; i++) {
            const y = random() * height;
            const n = i % channels.length;
            const x = curve(y, n) + (random() - 0.5) * 82;
            const size = 0.35 + random() * 1.7;
            ctx.globalAlpha = 0.19 + random() * 0.71;
            ctx.fillStyle = i % 11 < 3 ? '#c39afc' : '#ffcf76';
            ctx.fillRect(x, y, size, size);
        }
        ctx.globalAlpha = 1;
    });
    const floor = new THREE.Mesh(new THREE.PlaneGeometry(41.5, 31.5), new THREE.MeshStandardMaterial({
        color: 0xd6e0ff, map: resin, emissive: 0xadd3ff, emissiveMap: resin, emissiveIntensity: 0.78,
        metalness: 0.23, roughness: 0.29
    }));
    floor.name = 'TF_FLOW_RESIN_FLOOR';
    floor.rotation.x = -Math.PI / 2;
    floor.position.y = 0.024;
    floor.receiveShadow = true;
    floor.raycast = () => {};
    room.add(floor);

    const obsidian = new THREE.MeshStandardMaterial({ color: 0x111a2b, metalness: 0.35, roughness: 0.33 });
    const wallPanels = canvasTexture(1024, 384, (ctx, width, height) => {
        const glow = ctx.createLinearGradient(0, 0, 0, height);
        glow.addColorStop(0, '#253c65');
        glow.addColorStop(0.46, '#0b142b');
        glow.addColorStop(1, '#171f38');
        ctx.fillStyle = glow;
        ctx.fillRect(0, 0, width, height);
        for (let x = 0; x < width; x += 128) {
            ctx.fillStyle = '#060a15';
            ctx.fillRect(x, 0, 5, height);
            ctx.fillStyle = '#354e77';
            ctx.fillRect(x + 5, 0, 2, height);
        }
        for (const [y, color, thickness] of [[24, '#829dc6', 5], [31, '#395ef7', 3],
            [331, '#94744d', 3], [352, '#5b89f0', 5]]) {
            ctx.fillStyle = color;
            ctx.fillRect(0, y, width, thickness);
        }
    });
    const wallFinish = new THREE.MeshStandardMaterial({
        map: wallPanels, emissiveMap: wallPanels, emissive: 0x344e87, emissiveIntensity: 0.48,
        metalness: 0.24, roughness: 0.37
    });
    const pearl = new THREE.MeshStandardMaterial({ color: 0xb9cbea, metalness: 0.19, roughness: 0.34 });
    const gold = new THREE.MeshStandardMaterial({ color: 0xc79a57, metalness: 0.65, roughness: 0.38 });
    const cove = new THREE.MeshBasicMaterial({ color: 0x91caff });
    const ice = new THREE.MeshStandardMaterial({
        color: 0x2075aa, emissive: 0x13598f, emissiveIntensity: 0.64, metalness: 0.27,
        roughness: 0.44, flatShading: true
    });
    function add(geometry, material, x, y, z, parent = room) {
        const mesh = new THREE.Mesh(geometry, material);
        mesh.position.set(x, y, z);
        mesh.raycast = () => {};
        parent.add(mesh);
        return mesh;
    }
    function slab(width, height, depth, radius) {
        const w = width / 2;
        const d = depth / 2;
        const shape = new THREE.Shape();
        shape.moveTo(-w + radius, -d);
        shape.lineTo(w - radius, -d);
        shape.quadraticCurveTo(w, -d, w, -d + radius);
        shape.lineTo(w, d - radius);
        shape.quadraticCurveTo(w, d, w - radius, d);
        shape.lineTo(-w + radius, d);
        shape.quadraticCurveTo(-w, d, -w, d - radius);
        shape.lineTo(-w, -d + radius);
        shape.quadraticCurveTo(-w, -d, -w + radius, -d);
        return new THREE.ExtrudeGeometry(shape, {
            depth: height, bevelEnabled: false, steps: 1, curveSegments: 5
        }).rotateX(-Math.PI / 2);
    }

    // Sculpted ribs at the ends of the walls leave the central projection zones open.
    for (const side of [-1, 1]) {
        for (const z of [-12.7, 12.7]) {
            const path = new THREE.CatmullRomCurve3([
                new THREE.Vector3(side * 20.46, 0.3, z),
                new THREE.Vector3(side * 20.32, 3.0, z),
                new THREE.Vector3(side * 19.98, 6.8, z),
                new THREE.Vector3(side * 18.6, 9.8, z)
            ]);
            add(new THREE.TubeGeometry(path, 20, 0.23, 6, false), obsidian, 0, 0, 0);
            const trim = add(new THREE.TubeGeometry(path, 20, 0.038, 5, false), cove, -side * 0.21, 0, 0);
            trim.position.z = z > 0 ? -0.09 : 0.09;
        }
    }

    const desks = [];
    const desktop = slab(4.45, 0.15, 1.83, 0.32);
    const rim = slab(4.18, 0.035, 1.61, 0.30);
    const pedestal = slab(1.07, 1.10, 1.12, 0.22);
    const frame = new THREE.BoxGeometry(2.73, 1.29, 0.14);
    const screen = new THREE.PlaneGeometry(2.55, 1.10);
    const plaque = new THREE.PlaneGeometry(2.72, 0.33);
    for (const [index, station] of layout.entries()) {
        const desk = new THREE.Group();
        desk.name = 'TF_REFERENCE_DESK_' + station.id;
        desk.position.set(station.x, 0, station.z);
        desks.push(desk);
        room.add(desk);
        const isCool = ['ide', 'ai', 'music'].includes(station.id);
        const finish = isCool ? obsidian : pearl;
        for (const side of [-1, 1]) {
            add(pedestal, finish, side * 1.45, 0.03, 0, desk);
            if (isCool) {
                add(new THREE.IcosahedronGeometry(0.58, 0), ice, side * 1.45, 0.64, 0.26, desk)
                    .scale.set(0.85, 0.85, 0.62);
            }
        }
        add(rim, isCool ? gold : cove, 0, 1.12, 0, desk);
        add(desktop, finish, 0, 1.16, 0, desk);
        add(new THREE.BoxGeometry(0.24, 0.42, 0.21), obsidian, 0, 1.49, -0.44, desk);
        add(frame, isCool ? obsidian : pearl, 0, 2.15, -0.5, desk);
        const display = canvasTexture(512, 224, (ctx) => {
            ctx.fillStyle = '#101d32'; ctx.fillRect(0, 0, 512, 224);
            ctx.fillStyle = '#206393'; ctx.fillRect(20, 23, 3, 42);
            ctx.fillStyle = '#e1edf8'; ctx.font = '28px sans-serif';
            ctx.fillText(stationLabels[station.id], 39, 53);
            ctx.fillStyle = '#94b8ce'; ctx.font = '16px sans-serif';
            ctx.fillText('Approach and press E', 41, 89);
            ctx.strokeStyle = '#284a6b'; ctx.lineWidth = 2;
            ctx.beginPath(); ctx.moveTo(40, 125); ctx.lineTo(465, 125); ctx.stroke();
            for (let i = 0; i < 3; i++) {
                ctx.fillStyle = i === index % 3 ? '#518aa8' : '#203651';
                ctx.fillRect(40 + i * 145, 147, 127, 39);
            }
        });
        add(screen, new THREE.MeshBasicMaterial({ map: display }), 0, 2.15, -0.426, desk);
        const label = canvasTexture(512, 64, ctx => {
            ctx.fillStyle = '#142136'; ctx.fillRect(0, 0, 512, 64);
            ctx.fillStyle = '#d5e5f2'; ctx.font = '28px sans-serif'; ctx.textAlign = 'center';
            ctx.fillText(stationLabels[station.id], 256, 41);
        });
        add(plaque, new THREE.MeshBasicMaterial({ map: label }), 0, 1.09, 0.93, desk);
    }

    // Commit only after construction. The interaction array and its coordinates are retained.
    const originals = scene.children.filter(mesh => {
        const size = mesh.geometry?.parameters;
        if (!mesh.isMesh || !size) return false;
        const { x, y, z } = mesh.position;
        return layout.some(station => {
            const dx = x - station.x;
            const dz = z - station.z;
            if (size.width === 3.9 && size.height === 0.8) return dx === 0 && y === 3.28 && Math.abs(dz + 0.55) < 0.001;
            return size.depth !== undefined && Math.abs(dx) <= 1.9 &&
                Math.abs(dz) <= 0.84 && y >= 0.62 && y <= 2.15 &&
                [4.5, 0.13, 4.2, 2.55, 2.37, 2.2, 1.15, 0.42].includes(size.width);
        });
    });
    walls.forEach(mesh => { mesh.material = wallFinish; });
    tiles?.forEach(mesh => { mesh.visible = false; });
    originals.forEach(mesh => { mesh.visible = false; });
    const previousStudio = scene.getObjectByName('TF_TIER4_STUDIO_ARCHITECTURE');
    if (previousStudio) previousStudio.visible = false;
    scene.add(room);
    return { deskCount: desks.length, replacedMeshes: originals.length, wallCount: walls.length };
}

function startPreview(publicDir, openBrowser = false) {
    const read = (name) => fs.readFileSync(path.join(publicDir, name));
    const room = read('room.js');
    const hash = createHash('sha256').update(room).digest('hex');
    if (hash !== baselineHash) {
        throw new Error(`This preview needs the verified room.js from the sign() repair. Found SHA256 ${hash}.`);
    }

    const originalHtml = read('index.html').toString('utf8');
    const moduleTag = /<script type="module" src="\/room\.js"><\/script>/;
    if (!moduleTag.test(originalHtml)) {
        throw new Error('Expected room module tag was absent. The preview did not start.');
    }
    const style = read('style.css');
    const enhanced = Buffer.concat([room, Buffer.from(
        '\n;try { const studio = (' + applyTier4Preview.toString() + ')({ THREE, scene, earthStatus, textTexture });' +
        ' window.tfGraphicsRenderInfo = () => ({ ...renderer.info.render }); if (studio) (' + applyIntegratedGraphics.toString() + ')({ THREE, scene, renderer, sphere, earthStatus, studio }); }' +
        ' catch (error) { console.warn("Tier 4 visual preview unavailable", error); }\n'
    )]);
    const reference = Buffer.concat([enhanced, Buffer.from(
        '\n;try { const result = (' + applyReferenceLook.toString() + ')({ THREE, scene, stations });' +
        ' document.querySelector("#tf-preview-compare strong").textContent = "Reference interior applied";' +
        ' console.info("Reference interior applied", result); }' +
        ' catch (error) { document.querySelector("#tf-preview-compare strong").textContent = "Reference interior failed to load"; console.error(error); }\n'
    )]);
    const measurements = `<script>
        if (!new URLSearchParams(location.search).has('loggedin')) {
            history.replaceState(null, '', location.pathname + '?loggedin=1');
        }
        window.tfGraphicsSample = async (seconds = 20) => {
            if (!Number.isFinite(seconds) || seconds < 1 || seconds > 90) throw Error('Use 1–90 seconds.');
            const samples = [];
            const started = await new Promise(requestAnimationFrame);
            let last = started;
            while (last - started < seconds * 1000) {
                const now = await new Promise(requestAnimationFrame);
                samples.push(now - last);
                last = now;
            }
            samples.sort((a, b) => a - b);
            const percentile = p => Number(samples[Math.ceil(samples.length * p) - 1].toFixed(2));
            const canvas = document.querySelector('#scene canvas');
            const report = {
                profile: location.pathname,
                medianMs: percentile(0.5),
                p95Ms: percentile(0.95),
                frames: samples.length,
                resolution: canvas ? [canvas.width, canvas.height].join('x') : null,
                render: window.tfGraphicsRenderInfo?.(),
                navigationLoadMs: Math.round(performance.getEntriesByType('navigation')[0]?.loadEventEnd || 0)
            };
            console.table(report);
            return report;
        };
    </script>`;
    const compare = '<style>#tf-preview-compare{position:fixed;bottom:12px;right:12px;z-index:99999;' +
        'background:#131d28;color:#e8f3ff;border:1px solid #55738a;border-radius:6px;' +
        'padding:8px 12px;font:13px system-ui;text-decoration:none}#socketStatus{display:none}</style>';

    function html(source) {
        const links = [['reference', 'Reference interior'], ['tier4', 'Previous graphics'], ['original', 'Original room']];
        const navigation = '<nav id="tf-preview-compare" aria-label="Graphics preview">' +
            links.map(([path, label]) => path === source ? '<strong>' + label + '</strong>' :
                '<a href="/' + path + '">' + label + '</a>').join(' · ') + '</nav>';
        return originalHtml.replace(moduleTag, measurements + '<script type="module" src="/' + source + '.js"></script>')
            .replace('</head>', compare + '<style>#tf-preview-compare a{color:#b4deff}</style></head>')
            .replace('</body>', navigation + '</body>');
    }

    const server = http.createServer((request, response) => {
        const route = new URL(request.url, 'http://127.0.0.1');
        function send(status, type, payload) {
            response.writeHead(status, { 'Content-Type': type, 'Cache-Control': 'no-store' });
            response.end(payload);
        }
        if (request.method !== 'GET') {
            return send(405, 'text/plain', 'This visual preview is read-only.');
        }
        if (['/', '/reference', '/original', '/tier4'].includes(route.pathname)) {
            const source = route.pathname === '/' ? 'reference' : route.pathname.slice(1);
            return send(200, 'text/html; charset=utf-8', html(source));
        }
        if (route.pathname === '/graphics/earth.jpg') return send(200, 'image/jpeg', graphicsAssets.earth);
        if (route.pathname === '/graphics/clouds.jpg') return send(200, 'image/jpeg', graphicsAssets.clouds);
        if (route.pathname === '/style.css') return send(200, 'text/css; charset=utf-8', style);
        if (route.pathname === '/original.js') return send(200, 'text/javascript; charset=utf-8', room);
        if (route.pathname === '/reference.js') return send(200, 'text/javascript; charset=utf-8', reference);
        if (route.pathname === '/tier4.js') return send(200, 'text/javascript; charset=utf-8', enhanced);
        if (route.pathname === '/api/me') {
            return send(200, 'application/json', JSON.stringify({ login: 'local-preview', permission: 'read' }));
        }
        return send(404, 'application/json', '{"error":"Unavailable in the local graphics preview."}');
    });

    server.listen(0, '127.0.0.1', () => {
        const url = 'http://127.0.0.1:' + server.address().port + '/reference';
        console.log('TowerFlow studio preview, revision 5: ' + url);
        console.log('Close this terminal to stop the preview.');
        if (openBrowser && process.platform === 'win32') {
            const browser = spawn('rundll32.exe', ['url.dll,FileProtocolHandler', url], {
                detached: true, stdio: 'ignore', windowsHide: true
            });
            browser.on('error', () => console.log('Open the preview URL in your browser.'));
            browser.unref();
        }
    });
    return server;
}

if (require.main === module) {
    const desktop = path.join(process.env.USERPROFILE || os.homedir(), 'Desktop');
    // An explicit room path supports redirected desktops and nonstandard installs.
    const room = process.argv[2] || path.join(desktop, 'Towerflow_Team02_Private_Invite_Room', 'Towerflow_Collaboration_Room');
    try {
        startPreview(path.join(room, 'public'), true);
    } catch (error) {
        console.error('TowerFlow preview: ' + error.message);
        process.exitCode = 1;
    }
}

module.exports = { startPreview, applyTier4Preview, applyIntegratedGraphics, applyReferenceLook };
